mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Challenge_Complaints sd on sd.Sec_Id=sec.Sec_Id where sd.Scc_Id=#{sccId}

select sec.Sec_Name as secName, sec.Sec_Code as secCode, mn.* from Sec_Challenge_Complaints mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select sec.Sec_Name as secName, sec.Sec_Code as secCode, sec.Sec_Type as secType, sec.Sec_Bidding_Type as secBiddingType,
mn.* from Sec_Challenge_Complaints mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id where 1=1
order by pId asc limit #{params.start},#{params.size}
